mapper.select:
SELECT
IFNULL(SUM( bpmol.totalDeductionRechargeAmount ), 0) AS totalDeductionRechargeAmount,
IFNULL(SUM( bpmol.totalDeductionExpendAmount ), 0) AS totalDeductionExpendAmount,
IFNULL(SUM( bpmol.totalDeductionRefundAmount ), 0) AS totalDeductionRefundAmount
FROM
(
SELECT
bo.org_id,
IFNULL( bpmol.totalDeductionRechargeAmount, 0 ) AS totalDeductionRechargeAmount,
IFNULL( bpmol1.totalDeductionExpendAmount, 0 ) AS totalDeductionExpendAmount,
IFNULL( bpmol2.totalDeductionRefundAmount, 0 ) AS totalDeductionRefundAmount
FROM
base_organization bo
LEFT JOIN (
SELECT
bpmol.org_id,
SUM( bpmol.occur_amount) AS totalDeductionRechargeAmount
FROM
(
SELECT
bpmol.org_id,
bpmol.occur_amount
FROM
coupon_change_record bpmol

    AND bpmol.occur_type = 1
    and ISNULL(bpmol.order_id) = 0


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bpmol.occur_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bpmol.occur_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y') <= #{query.endDate}



) bpmol
GROUP BY
bpmol.org_id
) bpmol ON bo.org_id = bpmol.org_id
LEFT JOIN (
SELECT
bpmol.org_id,
SUM( bpmol.occur_amount) AS totalDeductionExpendAmount
FROM
(
SELECT
bpmol.org_id,
bpmol.occur_amount
FROM
coupon_change_record bpmol

    AND bpmol.occur_type = 2


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bpmol.occur_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bpmol.occur_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y') <= #{query.endDate}



) bpmol
GROUP BY
bpmol.org_id
) bpmol1 ON bo.org_id = bpmol1.org_id
LEFT JOIN (
SELECT
bpmol.org_id,
SUM(bpmol.occur_amount ) AS totalDeductionRefundAmount
FROM
(
SELECT
bpmol.org_id,
bpmol.occur_amount
FROM
coupon_change_record bpmol

    AND bpmol.occur_type = 3


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bpmol.occur_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bpmol.occur_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bpmol.occur_date, '%Y') <= #{query.endDate}



) bpmol
GROUP BY
bpmol.org_id
) bpmol2 ON bo.org_id = bpmol2.org_id
GROUP BY
bo.org_id
) bpmol

    and bpmol.org_id in

        #{item}
